css:
/* Проявление абзаца по словам. Меняется только opacity слов, привязанная к прокрутке.
   Окно проявления: первое слово загорается, когда верх абзаца на 80 % высоты экрана (--tsh-bottom: 20%),
   последнее — когда низ абзаца поднялся до 45 % (--tsh-top: 45%). Запасной JS читает эти же числа. */
.tsh {
  --tsh-dim: .25;          /* яркость ещё не прочитанных слов; на тёмной теме .3 */
  --tsh-top: 45%;
  --tsh-bottom: 20%;
  margin: 0;
  max-width: 30ch;
  font-size: clamp(24px, 3.2vw, 40px);
  font-weight: 600;
  line-height: 1.3;
  letter-spacing: -.01em;
  view-timeline: --tsh block;
  view-timeline-inset: var(--tsh-top) var(--tsh-bottom);
}
.tsh-kicker { margin: 0 0 16px; font-size: 15px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; color: var(--text-muted, #555b66); }
.tsh__w { opacity: var(--tsh-dim); }   /* слова появляются только после разбивки скриптом; до неё абзац виден целиком */
@keyframes tsh-word { from { opacity: var(--tsh-dim); } to { opacity: 1; } }
@media (prefers-reduced-motion: no-preference) {
  /* Chrome, Edge, Safari 26: ведёт сама прокрутка. Слово i загорается на своём отрезке шкалы (--p от 0 до 86 %) */
  @supports (animation-timeline: view()) {
    .tsh__w {
      animation: tsh-word 1ms linear both;   /* 1ms нужен Firefox; время на шкале прокрутки пересчитывается в долю пути */
      animation-timeline: --tsh;             /* строго ПОСЛЕ animation */
      animation-range: cover calc(var(--p, 0) * 1%) cover calc(var(--p, 0) * 1% + 14%); /* 14 % шкалы — мягкий «шлейф» в несколько слов */
    }
    .tsh.tsh-js .tsh__w { animation: none; } /* шкала замерла — ведёт JS */
  }
}
/* Уменьшение движения (уровень «убрать»): текст сразу целиком, без проявления */
@media (prefers-reduced-motion: reduce) {
  .tsh__w { opacity: 1 !important; animation: none !important; }
}
@media print {
  .tsh__w { opacity: 1 !important; animation: none !important; }
}

