// Проявление абзаца по словам: делит текст на слова; в Firefox и при замершей CSS-шкале ведёт прозрачность сам.
(() => {
  const els = [...document.querySelectorAll('[data-tsh]')];
  if (!els.length || matchMedia('(prefers-reduced-motion: reduce)').matches) return; // текст виден целиком
  const cssOk = !!(window.CSS && CSS.supports('animation-timeline', 'view()'));
  const js = []; let raf = 0;
  els.forEach((el) => {
    if (el.children.length) return; // внутри теги — не делим, абзац остаётся как есть
    const words = el.textContent.trim().split(/[ \t\r\n]+/); // &nbsp; остаётся внутри слова
    el.textContent = '';
    const ws = words.map((w, i) => {
      const s = document.createElement('span');
      s.className = 'tsh__w'; s.textContent = w;
      s.style.setProperty('--p', (words.length > 1 ? (i / (words.length - 1)) * 86 : 0).toFixed(2)); // место слова на шкале, %
      el.append(s, i < words.length - 1 ? ' ' : ''); // обычные пробелы между словами: копирование и чтение не страдают
      return s;
    });
    // CSS-шкала есть и не замерла (html, body { overflow-x: hidden } делает body контейнером прокрутки) — JS больше не нужен
    const src = ws[0].getAnimations()[0]?.timeline?.source;
    if (cssOk && !(src && src !== document.scrollingElement && src.scrollHeight <= src.clientHeight)) return;
    el.classList.add('tsh-js'); js.push([el, ws]);
  });
  const frame = () => {
    raf = 0;
    const vh = innerHeight;
    for (const [el, ws] of js) {
      const r = el.getBoundingClientRect();
      if (r.bottom < -vh || r.top > 2 * vh) continue; // далеко от экрана — не трогаем
      const cs = getComputedStyle(el), T = parseFloat(cs.getPropertyValue('--tsh-top')) / 100, B = parseFloat(cs.getPropertyValue('--tsh-bottom')) / 100;
      const dim = parseFloat(cs.getPropertyValue('--tsh-dim')) || 0.25;
      const p = (((1 - B) * vh - r.top) / ((1 - B - T) * vh + r.height)) * 100; // то же, что «cover %» в CSS
      ws.forEach((w, i) => { const k = Math.min(1, Math.max(0, (p - (ws.length > 1 ? (i / (ws.length - 1)) * 86 : 0)) / 14)); w.style.opacity = (dim + (1 - dim) * k).toFixed(3); });
    }
  };
  if (!js.length) return;
  const tick = () => { if (!raf) raf = requestAnimationFrame(frame); };
  addEventListener('scroll', tick, { passive: true, capture: true });
  addEventListener('resize', tick);
  tick();
})();

