// Только если GSAP уже есть в проекте: npm i gsap (Standard License, не MIT; SplitText входит в пакет), без CDN.
// Разметка и CSS те же, JS рецепта не подключать. Класс tsh-js снимает CSS-анимацию, прозрачность ведёт GSAP.
import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import { SplitText } from 'gsap/SplitText';
gsap.registerPlugin(ScrollTrigger, SplitText);

const el = document.querySelector('[data-tsh]');
const mm = gsap.matchMedia();
mm.add({ motion: '(prefers-reduced-motion: no-preference)', reduce: '(prefers-reduced-motion: reduce)' }, ({ conditions }) => {
  if (conditions.reduce) return; // абзац целиком, ничего не делим
  // SplitText сам ставит aria-label на абзац и aria-hidden на слова (aria: 'auto'), диктор читает текст целиком
  const split = SplitText.create(el, { type: 'words', wordsClass: 'tsh__w' });
  el.classList.add('tsh-js');
  gsap.fromTo(split.words, { opacity: 0.25 }, {
    opacity: 1, ease: 'none', stagger: 0.1, // в scrub только без кривой
    scrollTrigger: { trigger: el, start: 'top 80%', end: 'bottom 45%', scrub: true }, // то же окно, что в CSS
  });
  return () => { el.classList.remove('tsh-js'); split.revert(); };
});
